# Code generated by Claude
"""
How far the arms sag under their own weight at the real gains (control_gains.yaml: kp 70/70/70/60/10/10/10, kd 2.75/2.5/2/2/0.7/0.6/0.5), and that they hold still with gravity compensation on.

    MUJOCO_GL=egl python experiments/arm_sag_test.py

Gravity compensation is on in the simulator (robot_specs.ARM_ACTUATOR_SPECS["gravcomp_bodies"]; it assumes the real controller compensates for gravity, which is not confirmed). With it
on a position servo holds its target exactly; the numbers that matter for the real robot are the ones WITHOUT it, so both are measured, at the real gains and at the earlier placeholder
gains (kp 100/100/80/80/50/50/50, kd 10/10/8/8/5/5/5), at two poses: the home pose (arms at the side, elbows bent) and the extended ready pose of the left arm (the grasp approach; the right arm stays at home).

Each case: the robot stands on the floor with the pedestal at its staging height, both arms at the pose with the servo target equal to the pose, 3 s of simulation, then the joint errors
and the hand's (tool point) displacement from the target pose are read (both arms; the larger is reported).

Checks: with gravity compensation on, every joint holds within 0.05 degrees and the hand within 1 mm, and the arm is still (joint speeds under 1e-3 rad/s) at the end, at the real gains.
"""

import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.simulator import RobotSimulator  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402

OLD_KP, OLD_KV = (100, 100, 80, 80, 50, 50, 50), (10, 10, 8, 8, 5, 5, 5)
results = []
POSES = {"home": {"left": TASK_CFG["home_q_left"], "right": TASK_CFG["home_q_right"]},
         "extended (ready)": {"left": TASK_CFG["ready_q"], "right": TASK_CFG["home_q_right"]}}      # the left arm extended, the right at home


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def run_case(sim, pose, gains, gravcomp):
    m, d = sim.model, sim.data
    ids = {s: arm_ids(m, s) for s in ("left", "right")}
    gc = m.body_gravcomp.copy()
    kp0 = m.actuator_gainprm.copy(), m.actuator_biasprm.copy()
    if not gravcomp:
        m.body_gravcomp[:] = 0.0
    if gains == "old":
        for s in ids:
            for k, a in enumerate(ids[s]["act"]):
                m.actuator_gainprm[a, 0] = OLD_KP[k]
                m.actuator_biasprm[a, 1:3] = [-OLD_KP[k], -OLD_KV[k]]
    from src.gravity_ff import for_tests
    ff = for_tests(m) if gravcomp else None              # M185: "gravity compensation on" is the calculated feedforward unless the setting is "physics"
    mujoco.mj_resetData(m, d)
    d.qpos[0:7] = [0.0, 0.0, 0.1527, 1.0, 0.0, 0.0, 0.0]
    ped = m.actuator(robot_specs.PEDESTAL_SPECS["actuator_name"]).id
    d.qpos[m.joint("pedestal_joint").qposadr[0]] = TASK_CFG["pedestal_q"]
    ctrl = np.zeros(m.nu)
    ctrl[ped] = TASK_CFG["pedestal_q"]
    for s in ids:
        for a, j, q in zip(ids[s]["act"], ids[s]["qadr"], pose[s]):
            ctrl[a] = q
            d.qpos[j] = q
        ctrl[ids[s]["gripper"]] = 0.044
        for j in ids[s]["finger_jnt"]:
            d.qpos[m.jnt_qposadr[j]] = 0.044
    mujoco.mj_forward(m, d)
    tcp = {s: m.body(f"openarm_{s}_hand_tcp").id for s in ids}
    ref = {s: d.xpos[tcp[s]] - d.xpos[m.body("base_link").id] for s in ids}
    wheels = [m.actuator("left_motor").id, m.actuator("right_motor").id]
    base_dof = int(m.jnt_dofadr[m.joint("base_float").id])
    for _ in range(int(3.0 * robot_specs.PHYSICS_HZ)):
        d.ctrl[:] = ctrl
        if ff is not None:
            ff.apply(d.ctrl, d)
        d.ctrl[wheels] = 0.0
        d.qvel[base_dof:base_dof + 2] = 0.0
        d.qvel[base_dof + 3:base_dof + 6] = 0.0
        mujoco.mj_step(m, d)
    err = np.array([[d.qpos[j] - q for j, q in zip(ids[s]["qadr"], pose[s])] for s in ids])
    speed = max(abs(d.qvel[v]) for s in ids for v in ids[s]["vadr"])
    hand = max(float(np.linalg.norm((d.xpos[tcp[s]] - d.xpos[m.body("base_link").id]) - ref[s])) for s in ids)
    m.body_gravcomp[:] = gc
    m.actuator_gainprm[:], m.actuator_biasprm[:] = kp0
    return np.degrees(np.abs(err).max(axis=0)), hand * 1000, speed


def main():
    sim = RobotSimulator(pedestal_lift=robot_specs.PEDESTAL_SPECS, cameras=None)
    print(f"{'pose':18s} {'gains':6s} {'gravity comp':12s} | max |error| per joint 1..7 (deg){'':28s} | hand (mm) | speed")
    out = {}
    for pn, pose in POSES.items():
        for gains in ("real", "old"):
            for gc in (True, False):
                e, h, v = run_case(sim, pose, gains, gc)
                out[(pn, gains, gc)] = (e, h, v)
                print(f"{pn:18s} {gains:6s} {'on' if gc else 'OFF':12s} | " + " ".join(f"{x:6.2f}" for x in e) + f" | {h:9.1f} | {v:.1e}")
    print()
    for pn in POSES:
        e, h, v = out[(pn, "real", True)]
        check(f"{pn}, real gains, gravity compensation on: every joint holds within 0.05 degrees and the hand within 1 mm", e.max() < 0.05 and h < 1.0, f"{e.max():.3f} deg, {h:.2f} mm")
        check(f"{pn}, real gains, gravity compensation on: the arms are still at the end", v < 1e-3, f"{v:.1e} rad/s")
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
